},
["text"] = "You receive item: |cnIQ1:|Hitem:6270::::::::5:1482::14:::::::|h[Pattern: Blue Linen Vest]|h|r",
["id"] = "s0_305",
["timestamp"] = 1794032223,
},
{
["recordedBy"] = "Simonmage-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Eleanor Shackleton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Eleanor Shackleton says: Go on and have a seat near the fire and we can get started.",
["id"] = "s0_306",
["timestamp"] = 1794032292,
},
{
["recordedBy"] = "Simonmage-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Eleanor Shackleton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Eleanor Shackleton says: All you need to start a camp of your own is a basic campfire. Cooks can generally teach you how to make one of those.",
["id"] = "s0_307",
["timestamp"] = 1794032297,
},
{
["recordedBy"] = "Simonmage-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Eleanor Shackleton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Eleanor Shackleton says: Once your campfire is down, you can place all sorts of camp fixtures around it.",
["id"] = "s0_308",
["timestamp"] = 1794032305,
},
{
["recordedBy"] = "Simonmage-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Eleanor Shackleton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Eleanor Shackleton says: Sufficiently skilled leatherworkers, for example, can place a tent like this one behind me.",
["id"] = "s0_309",
["timestamp"] = 1794032311,
},
{
["recordedBy"] = "Simonmage-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Eleanor Shackleton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Eleanor Shackleton says: Every trade has something they can contribute to your camp, even fishermen!",
["id"] = "s0_310",
["timestamp"] = 1794032318,
},
{
["recordedBy"] = "Simonmage-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Eleanor Shackleton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Eleanor Shackleton says: Then, all you need to do is have a seat near the fire and soak it all in. After a few minutes of resting, you'll gain various boons that will help you in your travels.",
["id"] = "s0_311",
["timestamp"] = 1794032323,
},
{
["recordedBy"] = "Simonmage-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Eleanor Shackleton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
