},
["text"] = "You create: |cnIQ1:|Hitem:1113::::::::13:1482:::::::::|h[Conjured Bread]|h|rx4.",
["id"] = "s0_1647",
["timestamp"] = 1794079095,
},
{
["recordedBy"] = "Simonmage-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Tarnished Drudge",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Tarnished Drudge says: The light will purify us both!",
["id"] = "s0_1648",
["timestamp"] = 1794079107,
},
